package solution

import (
	"reflect"
	"testing"
	"time"
)

func TestListAssetsFilteringSortingAndPagination(t *testing.T) {
	records := []AssetRecord{
		{ID: "c", Labels: []string{"red", "large"}, Owner: "alice", Created: "2024-01-03T00:00:00Z", Modified: "2024-02-03T00:00:00Z"},
		{ID: "a", Labels: []string{"red"}, Owner: "alice", Created: "2024-01-01T00:00:00Z", Modified: "2024-02-01T00:00:00Z"},
		{ID: "b", Labels: []string{"red"}, Owner: "alice", Created: "2024-01-02T00:00:00Z", Modified: "2024-02-02T00:00:00Z"},
		{ID: "d", Labels: []string{"red"}, Owner: "Alice", Created: "2024-01-04T00:00:00Z", Modified: "2024-02-04T00:00:00Z"},
	}
	cutoff := time.Date(2024, 1, 2, 0, 0, 0, 0, time.UTC)
	rows, next, err := ListAssets(records, AssetQuery{Owner: "alice", Label: "red", CreatedOnOrAfter: cutoff, PageSize: 1})
	if err != nil {
		t.Fatalf("ListAssets returned error: %v", err)
	}
	if len(rows) != 1 || rows[0].ID != "b" || next != "1" {
		t.Fatalf("first page = %#v, cursor %q", rows, next)
	}
	rows, next, err = ListAssets(records, AssetQuery{Owner: "alice", Label: "red", CreatedOnOrAfter: cutoff, PageSize: 2, Cursor: next})
	if err != nil {
		t.Fatalf("second page returned error: %v", err)
	}
	if len(rows) != 1 || rows[0].ID != "c" || next != "" {
		t.Fatalf("second page = %#v, cursor %q", rows, next)
	}
}

func TestListAssetsDeepCopiesRows(t *testing.T) {
	records := []AssetRecord{{
		ID: "a", Labels: []string{"one", "two"}, Owner: "owner",
		Created: "2024-01-01T01:02:03Z", Modified: "2024-01-02T01:02:03Z",
		Attributes: map[string][]string{"k": {"v1", "v2"}},
	}}
	original := AssetRecord{ID: records[0].ID, Labels: append([]string(nil), records[0].Labels...), Owner: records[0].Owner, Created: records[0].Created, Modified: records[0].Modified, Attributes: map[string][]string{"k": append([]string(nil), records[0].Attributes["k"]...)}}
	rows, next, err := ListAssets(records, AssetQuery{PageSize: 10})
	if err != nil || next != "" || len(rows) != 1 {
		t.Fatalf("got %#v, cursor %q, err %v", rows, next, err)
	}
	if !reflect.DeepEqual(records[0], original) {
		t.Fatalf("input mutated during call: %#v", records[0])
	}
	rows[0].Labels[0] = "changed"
	rows[0].Attributes["k"][0] = "changed"
	rows[0].Attributes["new"] = []string{"x"}
	if !reflect.DeepEqual(records[0], original) {
		t.Fatalf("returned row aliases input: %#v", records[0])
	}
	records[0].Labels[1] = "later"
	records[0].Attributes["k"][1] = "later"
	if rows[0].Labels[1] != "two" || rows[0].Attributes["k"][1] != "v2" {
		t.Fatalf("row changed after input mutation: %#v", rows[0])
	}
}

func TestListAssetsEmptyInput(t *testing.T) {
	rows, next, err := ListAssets(nil, AssetQuery{PageSize: 1, Cursor: "0"})
	if err != nil || next != "" {
		t.Fatalf("got cursor %q, err %v", next, err)
	}
	if rows == nil || len(rows) != 0 {
		t.Fatalf("rows = %#v, want non-nil empty slice", rows)
	}
}

func TestListAssetsValidatesAllRecordsBeforeFiltering(t *testing.T) {
	cases := []struct {
		name    string
		records []AssetRecord
	}{
		{"bad created", []AssetRecord{{ID: "x", Owner: "excluded", Created: "bad", Modified: "2024-01-01T00:00:00Z"}}},
		{"bad modified", []AssetRecord{{ID: "x", Owner: "excluded", Created: "2024-01-01T00:00:00Z", Modified: "bad"}}},
		{"empty id", []AssetRecord{{ID: "", Owner: "excluded", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}}},
		{"duplicate excluded ids", []AssetRecord{
			{ID: "x", Owner: "excluded", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"},
			{ID: "x", Owner: "excluded", Created: "2024-01-02T00:00:00Z", Modified: "2024-01-02T00:00:00Z"},
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			rows, cursor, err := ListAssets(tc.records, AssetQuery{Owner: "wanted", PageSize: 1})
			if err == nil || rows != nil || cursor != "" {
				t.Fatalf("got rows %#v, cursor %q, err %v", rows, cursor, err)
			}
		})
	}
}

func TestListAssetsRejectsPageSizeAndInvalidCursors(t *testing.T) {
	records := []AssetRecord{{ID: "a", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}}
	for _, size := range []int{0, -1} {
		rows, cursor, err := ListAssets(records, AssetQuery{PageSize: size})
		if err == nil || rows != nil || cursor != "" {
			t.Fatalf("PageSize %d: rows %#v, cursor %q, err %v", size, rows, cursor, err)
		}
	}
	for _, cursor := range []string{"+0", "-0", " 0", "0 ", "00", "01", "1x", "184467440737095516160", "2"} {
		t.Run(cursor, func(t *testing.T) {
			rows, next, err := ListAssets(records, AssetQuery{PageSize: 1, Cursor: cursor})
			if err == nil || rows != nil || next != "" {
				t.Fatalf("cursor %q: rows %#v, next %q, err %v", cursor, rows, next, err)
			}
		})
	}
}

func TestListAssetsCursorAtMatchCountIsValid(t *testing.T) {
	records := []AssetRecord{{ID: "a", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}}
	rows, cursor, err := ListAssets(records, AssetQuery{PageSize: 1, Cursor: "1"})
	if err != nil || cursor != "" || rows == nil || len(rows) != 0 {
		t.Fatalf("got rows %#v, cursor %q, err %v", rows, cursor, err)
	}
}

